sys_script_include.script:
// Script Include: ReferenceCacheService
// Camada: INFRAESTRUTURA — cacheia dados de referência (serviços) na sessão,
// com invalidação via Business Rule ao alterar x_espaco_servico.
var ReferenceCacheService = Class.create();
ReferenceCacheService.prototype = {
    initialize: function() {
        this.KEY = 'x_espaco.servicos.cache';
    },

    /**
     * Retorna a lista de serviços, populando o cache de sessão se necessário.
     * @returns {Array}
     */
    getServicos: function() {
        var cache = gs.getSession().getProperty(this.KEY);
        if (cache) {
            return JSON.parse(cache);
        }
        var list = [];
        var gr = new GlideRecord('x_espaco_servico');
        gr.orderBy('nome');
        gr.query();
        while (gr.next()) {
            list.push({
                sys_id: gr.getUniqueValue(),
                nome: gr.getValue('nome'),
                area: gr.getValue('area_corporal'),
                duracao: gr.getValue('duracao_minutos')
            });
        }
        gs.getSession().putProperty(this.KEY, JSON.stringify(list));
        return list;
    },

    /**
     * Invalida o cache de serviços (chamado pela Business Rule de x_espaco_servico).
     */
    invalidar: function() {
        gs.getSession().clearProperty(this.KEY);
    },

    type: 'ReferenceCacheService'
};
